1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21		"time"
22	)
23	
24	// Version is the baseline release identifier.
25	const Version = "0.1.0"
26	
27	const metricsPath = "/api/v1/metrics"
28	
29	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
30	
31	type health struct {
32		Status  string `json:"status"`
33		Service string `json:"service"`
34		Version string `json:"version"`
35	}
36	
37	// series is one uniquely identified time series: name + full label set.
38	type series struct {
39		name   string
40		typ    string
41		labels map[string]string
42	
43		// counter/gauge state
44		value float64
45	
46		// histogram state
47		bucketBounds []float64 // strictly increasing, fixed at first write
48		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
49		count        int64
50		sum          float64
51	
52		// history holds accepted samples in commit order for range queries.
53		// Entries older than the retention window are ignored at query time;
54		// evicting them never touches the cumulative state above.
55		history []historyPoint
56	}
57	
58	type metricStore struct {
59		mu     sync.RWMutex
60		series map[string]*series
61	
62		// alert rules keyed by rule id; guarded by mu so rule replacement and
63		// alert evaluation are atomic with metric commits.
64		rules map[string]*alertRule
65	
66		// silences keyed by silence id; same lock so alert evaluation reads
67		// metrics, rules and silences from one consistent snapshot.
68		silences map[string]*silence
69	
70		// inhibit rules keyed by rule id; same lock so alert evaluation also
71		// reads inhibit rules from the same consistent snapshot.
72		inhibitions map[string]*inhibitRule
73	
74		// notification routes keyed by route id; same lock so the notification
75		// plan reads routes from the same snapshot as alert evaluation.
76		notificationRoutes map[string]*notificationRoute
77	
78		// SLO definitions keyed by SLO id; same lock so status evaluation reads
79		// definitions and counters from one consistent snapshot.
80		slos map[string]*sloDefinition
81	
82		// Log entries keyed by entry id; same lock so log commits and retrieval
83		// read one consistent snapshot. logOrder is the submission-order FIFO
84		// of ids used for eviction; logSeq is the commit sequence that anchors
85		// paginated read snapshots.
86		logs     map[string]*logEntry
87		logOrder []string
88		logSeq   int64
89	
90		// Spans keyed by tenant-unique "trace_id\x00span_id"; same lock so span
91		// commits and trace reads share the logs snapshot they join against.
92		// spanSeq is the commit sequence that anchors paginated trace searches.
93		spans   map[string]*span
94		spanSeq int64
95	
96		// Deterministic ingest sampling policy; same lock so a policy swap is
97		// atomic with respect to the log/span commits it governs.
98		sampling samplingPolicy
99	
100		// Discovery target snapshot; same lock so reloads swap one immutable
101		// snapshot pointer and queries always read a consistent generation.
102		discovery *discoverySnapshot
103	
104		// scrapeBaseline holds the last committed cumulative counter value per
105		// scraped series key; same lock so a target's batch and its baseline
106		// update commit atomically.
107		scrapeBaseline map[string]float64
108	}
109	
110	func newMetricStore() *metricStore {
111		return &metricStore{
112			series:             make(map[string]*series),
113			rules:              make(map[string]*alertRule),
114			silences:           make(map[string]*silence),
115			inhibitions:        make(map[string]*inhibitRule),
116			notificationRoutes: make(map[string]*notificationRoute),
117			slos:               make(map[string]*sloDefinition),
118			logs:               make(map[string]*logEntry),
119			spans:              make(map[string]*span),
120			sampling:           defaultSamplingPolicy(),
121			discovery:          emptyDiscoverySnapshot(),
122			scrapeBaseline:     make(map[string]float64),
123		}
124	}
125	
126	// validatedSample is a sample that passed all format and value checks.
127	type validatedSample struct {
128		key     string
129		name    string
130		typ     string
131		labels  map[string]string
132		value   float64
133		buckets []float64 // non-nil for histograms
134		ts      time.Time
135	}
136	
137	// checkAndApply validates the batch against the current state (and against
138	// itself) and then commits it in array order. A false result signals a type or
139	// bucket-boundary conflict; in that case no state is mutated.
140	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
141		s.mu.Lock()
142		defer s.mu.Unlock()
143	
144		// First pass: conflict detection against committed state and earlier
145		// samples in the same batch.
146		resolved := make(map[string]*series, len(batch))
147		for _, sm := range batch {
148			existing, ok := s.series[sm.key]
149			if !ok {
150				if shadow, seen := resolved[sm.key]; seen {
151					existing, ok = shadow, true
152				}
153			}
154			if ok {
155				if existing.typ != sm.typ {
156					return false
157				}
158				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
159					return false
160				}
161				resolved[sm.key] = existing
162				continue
163			}
164			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
165		}
166	
167		// Second pass: commit in order.
168		for _, sm := range batch {
169			cur, ok := s.series[sm.key]
170			if !ok {
171				cur = &series{
172					name:         sm.name,
173					typ:          sm.typ,
174					labels:       sm.labels,
175					bucketBounds: append([]float64(nil), sm.buckets...),
176				}
177				if sm.typ == "histogram" {
178					cur.bucketCounts = make([]int64, len(sm.buckets))
179				}
180				s.series[sm.key] = cur
181			}
182			switch sm.typ {
183			case "counter":
184				cur.value += sm.value
185			case "gauge":
186				cur.value = sm.value
187			case "histogram":
188				cur.count++
189				cur.sum += sm.value
190				for i, bound := range cur.bucketBounds {
191					if sm.value <= bound {
192						cur.bucketCounts[i]++
193					}
194				}
195			}
196			cur.history = append(cur.history, historyPoint{ts: sm.ts, value: sm.value})
197		}
198		return true
199	}
200	
201	type seriesOutput struct {
202		Name    string            `json:"name"`
203		Type    string            `json:"type"`
204		Labels  map[string]string `json:"labels"`
205		Value   *float64          `json:"value,omitempty"`
206		Count   *int64            `json:"count,omitempty"`
207		Sum     *float64          `json:"sum,omitempty"`
208		Buckets []bucketOutput    `json:"buckets,omitempty"`
209	}
210	
211	type bucketOutput struct {
212		LE    float64 `json:"le"`
213		Count int64   `json:"count"`
214	}
215	
216	// query returns matching series as ready-to-encode outputs. A series matches
217	// when its name equals name exactly and it contains every selector label.
218	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
219		s.mu.RLock()
220		defer s.mu.RUnlock()
221	
222		out := make([]seriesOutput, 0)
223		for _, cur := range s.series {
224			if cur.name != name {
225				continue
226			}
227			matched := true
228			for k, v := range selector {
229				got, ok := cur.labels[k]
230				if !ok || got != v {
231					matched = false
232					break
233				}
234			}
235			if !matched {
236				continue
237			}
238			item := seriesOutput{
239				Name:   cur.name,
240				Type:   cur.typ,
241				Labels: copyLabels(cur.labels),
242			}
243			switch cur.typ {
244			case "counter", "gauge":
245				v := cur.value
246				item.Value = &v
247			case "histogram":
248				c, sum := cur.count, cur.sum
249				item.Count = &c
250				item.Sum = &sum
251				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
252				for i, bound := range cur.bucketBounds {
253					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
254				}
255			}
256			out = append(out, item)
257		}
258	
259		sort.Slice(out, func(i, j int) bool {
260			return compareLabels(out[i].Labels, out[j].Labels) < 0
261		})
262		return out
263	}
264	
265	// compareLabels imposes a normalized lexicographic order on full label sets:
266	// keys are sorted, then (key, value) pairs are compared element-wise, and a
267	// shorter pair list sorts first when it is a prefix of a longer one.
268	func compareLabels(a, b map[string]string) int {
269		ka := sortedKeys(a)
270		kb := sortedKeys(b)
271		n := len(ka)
272		if len(kb) < n {
273			n = len(kb)
274		}
275		for i := 0; i < n; i++ {
276			if ka[i] != kb[i] {
277				return strings.Compare(ka[i], kb[i])
278			}
279			if a[ka[i]] != b[kb[i]] {
280				return strings.Compare(a[ka[i]], b[kb[i]])
281			}
282		}
283		switch {
284		case len(ka) < len(kb):
285			return -1
286		case len(ka) > len(kb):
287			return 1
288		default:
289			return 0
290		}
291	}
292	
293	func sortedKeys(m map[string]string) []string {
294		keys := make([]string, 0, len(m))
295		for k := range m {
296			keys = append(keys, k)
297		}
298		sort.Strings(keys)
299		return keys
300	}
301	
302	func copyLabels(in map[string]string) map[string]string {
303		out := make(map[string]string, len(in))
304		for k, v := range in {
305			out[k] = v
306		}
307		return out
308	}
309	
310	// seriesKey builds a collision-free identity from name + unordered labels.
311	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
312	// so length-prefixed values remove any ambiguity from arbitrary label values.
313	func seriesKey(name string, labels map[string]string) string {
314		var b strings.Builder
315		b.WriteString(name)
316		for _, k := range sortedKeys(labels) {
317			b.WriteByte(0)
318			b.WriteString(k)
319			b.WriteByte(0)
320			v := labels[k]
321			b.WriteString(strconv.Itoa(len(v)))
322			b.WriteByte(0)
323			b.WriteString(v)
324		}
325		return b.String()
326	}
327	
328	func equalBuckets(a, b []float64) bool {
329		if len(a) != len(b) {
330			return false
331		}
332		for i := range a {
333			if a[i] != b[i] {
334				return false
335			}
336		}
337		return true
338	}
339	
340	// Handler returns the HTTP surface served by SignalWatch.
341	func Handler() http.Handler {
342		return newHandler(newTenantRegistry())
343	}
344	
345	func newHandler(registry *tenantRegistry) http.Handler {
346		mux := http.NewServeMux()
347	
348		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
349			if r.Method != http.MethodGet {
350				w.Header().Set("Allow", http.MethodGet)
351				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
352				return
353			}
354			w.Header().Set("Content-Type", "application/json; charset=utf-8")
355			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
356		})
357	
358		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
359			switch r.Method {
360			case http.MethodGet:
361				handleMetricsGet(w, r)
362			case http.MethodPost:
363				handleMetricsPost(w, r)
364			default:
365				w.Header().Set("Allow", "GET, POST")
366				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
367			}
368		})
369	
370		registerAlertHandlers(mux)
371		registerSilenceHandlers(mux)
372		registerInhibitHandlers(mux)
373		registerNotificationRouteHandlers(mux)
374		registerSLOHandlers(mux)
375		registerQueryHandler(mux)
376		registerMetricRangeHandler(mux)
377		registerQueryRangeHandler(mux)
378		registerLogHandlers(mux)
379		registerSpanHandlers(mux)
380		registerSamplingPolicyHandlers(mux)
381		registerDiscoveryTargetHandlers(mux)
382	
383		return withTenants(mux, registry)
384	}
385	
386	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
387		// All samples in the request share this single receive instant: it is the
388		// default timestamp and the anchor for the accepted timestamp window.
389		receivedAt := time.Now()
390		store := tenantStore(r)
391		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
392		if err != nil || mediaType != "application/json" {
393			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
394			return
395		}
396	
397		body, err := io.ReadAll(r.Body)
398		if err != nil {
399			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
400			return
401		}
402	
403		batch, code := decodeMetricsBatch(body, receivedAt)
404		if code != "" {
405			writeAPIError(w, code, http.StatusBadRequest)
406			return
407		}
408	
409		if !store.checkAndApply(batch) {
410			writeAPIError(w, "metric_conflict", http.StatusConflict)
411			return
412		}
413	
414		w.Header().Set("Content-Type", "application/json; charset=utf-8")
415		w.WriteHeader(http.StatusAccepted)
416		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
417	}
418	
419	type metricsEnvelope struct {
420		Samples *[]json.RawMessage `json:"samples"`
421	}
422	
423	type rawSample struct {
424		Name      *string            `json:"name"`
425		Type      *string            `json:"type"`
426		Labels    *map[string]string `json:"labels"`
427		Value     *float64           `json:"value"`
428		Buckets   *[]float64         `json:"buckets"`
429		Timestamp *string            `json:"timestamp"`
430	}
431	
432	// decodeMetricsBatch performs every format and value check, including the
433	// optional per-sample timestamp. It never returns a partially validated
434	// batch. The returned error code is empty on success.
435	func decodeMetricsBatch(body []byte, receivedAt time.Time) ([]validatedSample, string) {
436		var env metricsEnvelope
437		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
438			return nil, "invalid_metrics"
439		}
440	
441		batch := make([]validatedSample, 0, len(*env.Samples))
442		for _, raw := range *env.Samples {
443			var sm rawSample
444			if !strictDecode(raw, &sm) {
445				return nil, "invalid_metrics"
446			}
447			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
448				return nil, "invalid_metrics"
449			}
450			name, typ := *sm.Name, *sm.Type
451			if !identPattern.MatchString(name) {
452				return nil, "invalid_metrics"
453			}
454			if typ != "counter" && typ != "gauge" && typ != "histogram" {
455				return nil, "invalid_metrics"
456			}
457			labels := *sm.Labels
458			if labels == nil {
459				return nil, "invalid_metrics" // explicit null labels
460			}
461			for k := range labels {
462				if !identPattern.MatchString(k) {
463					return nil, "invalid_metrics"
464				}
465			}
466			value := *sm.Value
467			if math.IsNaN(value) || math.IsInf(value, 0) {
468				return nil, "invalid_metrics" // encoding/json already rejects NaN/Inf tokens
469			}
470			if typ == "counter" && value < 0 {
471				return nil, "invalid_metrics"
472			}
473	
474			var buckets []float64
475			if typ == "histogram" {
476				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
477					return nil, "invalid_metrics"
478				}
479				buckets = append([]float64(nil), (*sm.Buckets)...)
480			} else if sm.Buckets != nil {
481				return nil, "invalid_metrics" // buckets only valid on histograms
482			}
483	
484			// The timestamp is optional; every sample without one shares the
485			// request's receive instant.
486			ts := receivedAt
487			if sm.Timestamp != nil {
488				parsed, err := time.Parse(time.RFC3339Nano, *sm.Timestamp)
489				if err != nil {
490					return nil, "invalid_metrics"
491				}
492				ts = parsed
493			}
494			if ts.Before(receivedAt.Add(-metricRetention)) || ts.After(receivedAt.Add(maxFutureSkew)) {
495				return nil, "metric_timestamp_out_of_range"
496			}
497	
498			batch = append(batch, validatedSample{
499				key:     seriesKey(name, labels),
500				name:    name,
501				typ:     typ,
502				labels:  copyLabels(labels),
503				value:   value,
504				buckets: buckets,
505				ts:      ts,
506			})
507		}
508		return batch, ""
509	}
510	
511	func validBuckets(buckets []float64) bool {
512		if len(buckets) == 0 {
513			return false
514		}
515		prev := math.Inf(-1)
516		for _, b := range buckets {
517			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
518				return false
519			}
520			prev = b
521		}
522		return true
523	}
524	
525	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
526	// values and non-object payloads for struct targets.
527	func strictDecode(data []byte, target any) bool {
528		dec := json.NewDecoder(bytes.NewReader(data))
529		dec.DisallowUnknownFields()
530		if err := dec.Decode(target); err != nil {
531			return false
532		}
533		var extra json.RawMessage
534		if err := dec.Decode(&extra); err != io.EOF {
535			return false
536		}
537		return true
538	}
539	
540	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
541		store := tenantStore(r)
542		values, err := url.ParseQuery(r.URL.RawQuery)
543		if err != nil {
544			writeAPIError(w, "invalid_query", http.StatusBadRequest)
545			return
546		}
547	
548		names := values["name"]
549		if len(names) == 0 || !identPattern.MatchString(names[0]) {
550			writeAPIError(w, "invalid_query", http.StatusBadRequest)
551			return
552		}
553	
554		selector := make(map[string]string)
555		for key, vals := range values {
556			if !strings.HasPrefix(key, "label.") {
557				continue
558			}
559			labelKey := strings.TrimPrefix(key, "label.")
560			if !identPattern.MatchString(labelKey) {
561				writeAPIError(w, "invalid_query", http.StatusBadRequest)
562				return
563			}
564			for _, v := range vals[1:] {
565				if v != vals[0] {
566					writeAPIError(w, "invalid_query", http.StatusBadRequest)
567					return
568				}
569			}
570			selector[labelKey] = vals[0]
571		}
572	
573		seriesList := store.query(names[0], selector)
574		w.Header().Set("Content-Type", "application/json; charset=utf-8")
575		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
576	}
577	
578	func writeAPIError(w http.ResponseWriter, code string, status int) {
579		w.Header().Set("Content-Type", "application/json; charset=utf-8")
580		w.WriteHeader(status)
581		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
582	}
583

