201		s.mu.RLock()
202		defer s.mu.RUnlock()
203		r, ok := s.rules[id]
204		return r, ok
205	}
206	
207	func (s *metricStore) deleteRule(id string) bool {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		if _, ok := s.rules[id]; !ok {
211			return false
212		}
213		delete(s.rules, id)
214		return true
215	}
216	
217	// snapshotRules returns all rules sorted by id. Rule objects are immutable,
218	// so the pointers stay safe after the lock is released.
219	func (s *metricStore) snapshotRules() []*alertRule {
220		s.mu.RLock()
221		defer s.mu.RUnlock()
222		out := make([]*alertRule, 0, len(s.rules))
223		for _, r := range s.rules {
224			out = append(out, r)
225		}
226		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
227		return out
228	}
229	
230	// selectorSum sums current values of all matching counter/gauge series.
231	// ok is false when no counter/gauge series matches; histograms are ignored,
232	// so a selector matching histograms only counts as unavailable.
233	func (s *metricStore) selectorSum(sel *ruleSelector) (sum float64, ok bool) {
234		for _, cur := range s.series {
235			if cur.typ != "counter" && cur.typ != "gauge" {
236				continue
237			}
238			if cur.name != sel.metric {
239				continue
240			}
241			matched := true
242			for k, v := range sel.labels {
243				got, exists := cur.labels[k]
244				if !exists || got != v {
245					matched = false
246					break
247				}
248			}
249			if !matched {
250				continue
251			}
252			sum += cur.value
253			ok = true
254		}
255		return sum, ok
256	}
257	
258	type alertOutput struct {
259		ID            string   `json:"id"`
260		State         string   `json:"state"`
261		Value         *float64 `json:"value"`
262		Silenced      bool     `json:"silenced"`
263		SilenceIDs    []string `json:"silence_ids"`
264		Inhibited     bool     `json:"inhibited"`
265		InhibitionIDs []string `json:"inhibition_ids"`
266	}
267	
268	// evalAlerts computes every rule against a single consistent snapshot of
269	// metrics, rules, silences and inhibit rules; results are sorted by rule id.
270	// Original state, value and silencing are evaluated first; inhibition is then
271	// applied to the original firing states so silenced or inhibited alerts still
272	// act as inhibition sources.
273	func (s *metricStore) evalAlerts() []alertOutput {
274		s.mu.RLock()
275		defer s.mu.RUnlock()
276		return s.evalAlertsLocked()
277	}
278	
279	// evalAlertsLocked computes every rule against a single consistent snapshot
280	// already held by the caller. Callers that also need other state (e.g. the
281	// notification plan's routes) share one snapshot by holding s.mu themselves.
282	func (s *metricStore) evalAlertsLocked() []alertOutput {
283		rules := make([]*alertRule, 0, len(s.rules))
284		for _, r := range s.rules {
285			rules = append(rules, r)
286		}
287		sort.Slice(rules, func(i, j int) bool { return rules[i].id < rules[j].id })
288	
289		silences := make([]*silence, 0, len(s.silences))
290		for _, sil := range s.silences {
291			silences = append(silences, sil)
292		}
293		inhibitRules := make([]*inhibitRule, 0, len(s.inhibitions))
294		for _, ir := range s.inhibitions {
295			inhibitRules = append(inhibitRules, ir)
296		}
297		// Evaluation instant and silence windowing share the snapshot.
298		now := time.Now()
299		activeByRule := activeSilencesByRule(silences, now)
300	
301		out := make([]alertOutput, 0, len(rules))
302		for _, r := range rules {
303			al := alertOutput{ID: r.id, State: "inactive", SilenceIDs: []string{}, InhibitionIDs: []string{}}
304	
305			var value float64
306			if r.kind == "threshold" {
307				sum, ok := s.selectorSum(r.left)
308				if !ok {
309					al.State = "no_data"
310					out = append(out, al)
311					continue
312				}
313				value = sum
314			} else {
315				num, numOK := s.selectorSum(r.left)
316				den, denOK := s.selectorSum(r.right)
317				if !numOK || !denOK || den == 0 {
318					al.State = "no_data"
319					out = append(out, al)
320					continue
321				}
322				value = num / den
323			}
324	
325			v := value
326			al.Value = &v
327			if compareHolds(r.operator, value, r.threshold) {
328				al.State = "firing"
329				if hits := activeByRule[r.id]; len(hits) > 0 {
330					al.Silenced = true
331					al.SilenceIDs = append([]string(nil), hits...)
332				}
333			}
334			out = append(out, al)
335		}
336	
337		applyInhibitions(out, inhibitRules)
338		return out
339	}
340	
341	// applyInhibitions annotates alerts with the inhibit rules that hit them. A
342	// rule hits an alert when the alert's original state is firing and at least
343	// one existing source alert's original state is firing. Sources fire
344	// regardless of their own silenced/inhibited flags, and the target's state,
345	// value and silencing are left untouched.
346	func applyInhibitions(alerts []alertOutput, inhibitRules []*inhibitRule) {
347		firing := make(map[string]bool, len(alerts))
348		for i := range alerts {
349			if alerts[i].State == "firing" {
350				firing[alerts[i].ID] = true
351			}
352		}
353	
354		for i := range alerts {
355			if alerts[i].State != "firing" {
356				continue
357			}
358			var hits []string
359			for _, ir := range inhibitRules {
360				if !containsString(ir.targetRuleIDs, alerts[i].ID) {
361					continue
362				}
363				for _, sourceID := range ir.sourceRuleIDs {
364					if firing[sourceID] {
365						hits = append(hits, ir.id)
366						break
367					}
368				}
369			}
370			if len(hits) > 0 {
371				sort.Strings(hits)
372				alerts[i].Inhibited = true
373				alerts[i].InhibitionIDs = hits
374			}
375		}
376	}
377	
378	func containsString(list []string, want string) bool {
379		for _, v := range list {
380			if v == want {
381				return true
382			}
383		}
384		return false
385	}
386	
387	func compareHolds(operator string, value, threshold float64) bool {
388		switch operator {
389		case "gt":
390			return value > threshold
391		case "gte":
392			return value >= threshold
393		case "lt":
394			return value < threshold
395		case "lte":
396			return value <= threshold
397		}
398		return false
399	}
400	
401	// ---- HTTP handlers ---------------------------------------------------------
402	
403	func registerAlertHandlers(mux *http.ServeMux) {
404		mux.HandleFunc(alertRulesPath, func(w http.ResponseWriter, r *http.Request) {
405			if r.Method != http.MethodGet {
406				w.Header().Set("Allow", http.MethodGet)
407				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
408				return
409			}
410			store := tenantStore(r)
411			rules := store.snapshotRules()
412			body := make([]any, 0, len(rules))
413			for _, rule := range rules {
414				body = append(body, ruleWireJSON(rule))
415			}
416			writeJSON(w, http.StatusOK, map[string]any{"rules": body})
417		})
418	
419		mux.HandleFunc(alertRulesPrefix, func(w http.ResponseWriter, r *http.Request) {
420			store := tenantStore(r)
421			id := strings.TrimPrefix(r.URL.Path, alertRulesPrefix)
422			switch r.Method {
423			case http.MethodGet, http.MethodDelete:
424				// Reads and deletions can only address an existing, syntactically
425				// valid rule id; anything else is simply not found.
426				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
427					writeAPIError(w, "rule_not_found", http.StatusNotFound)
428					return
429				}
430				if r.Method == http.MethodGet {
431					handleRuleGet(w, id, store)
432				} else {
433					handleRuleDelete(w, id, store)
434				}
435			case http.MethodPut:
436				// A structurally nested path is outside this resource subtree;
437				// an identifier-shaped but invalid id is a bad rule identifier.
438				if id == "" || strings.Contains(id, "/") {
439					writeAPIError(w, "rule_not_found", http.StatusNotFound)
440					return
441				}
442				if !identPattern.MatchString(id) {
443					writeAPIError(w, "invalid_rule", http.StatusBadRequest)
444					return
445				}
446				handleRulePut(w, r, id, store)
447			default:
448				w.Header().Set("Allow", "GET, PUT, DELETE")
449				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
450			}
451		})
452	
453		mux.HandleFunc(alertsPath, func(w http.ResponseWriter, r *http.Request) {
454			if r.Method != http.MethodGet {
455				w.Header().Set("Allow", http.MethodGet)
456				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
457				return
458			}
459			writeJSON(w, http.StatusOK, map[string]any{"alerts": tenantStore(r).evalAlerts()})
460		})
461	}
462	
463	func handleRuleGet(w http.ResponseWriter, id string, store *metricStore) {
464		rule, ok := store.getRule(id)
465		if !ok {
466			writeAPIError(w, "rule_not_found", http.StatusNotFound)
467			return
468		}
469		writeJSON(w, http.StatusOK, ruleWireJSON(rule))
470	}
471	
472	func handleRulePut(w http.ResponseWriter, r *http.Request, id string, store *metricStore) {
473		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
474		if err != nil || mediaType != "application/json" {
475			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
476			return
477		}
478	
479		body, err := io.ReadAll(r.Body)
480		if err != nil {
481			writeAPIError(w, "invalid_rule", http.StatusBadRequest)
482			return
483		}
484	
485		rule, ok := decodeRule(body)
486		if !ok {
487			writeAPIError(w, "invalid_rule", http.StatusBadRequest)
488			return
489		}
490		rule.id = id
491	
492		created := store.putRule(rule)
493		status := http.StatusOK
494		if created {
495			status = http.StatusCreated
496		}
497		writeJSON(w, status, ruleWireJSON(rule))
498	}
499	
500	func handleRuleDelete(w http.ResponseWriter, id string, store *metricStore) {
501		if !store.deleteRule(id) {
502			writeAPIError(w, "rule_not_found", http.StatusNotFound)
503			return
504		}
505		w.WriteHeader(http.StatusNoContent)
506	}
507	
508	func writeJSON(w http.ResponseWriter, status int, payload any) {
509		w.Header().Set("Content-Type", "application/json; charset=utf-8")
510		w.WriteHeader(status)
511		_ = json.NewEncoder(w).Encode(payload)
512	}
