21	var spanStatuses = map[string]bool{
22		"unset": true,
23		"ok":    true,
24		"error": true,
25	}
26	
27	// span is one committed trace span. Spans are immutable once stored.
28	type span struct {
29		traceID      string
30		spanID       string
31		parentSpanID string // "" when parent_span_id is null
32		service      string
33		name         string
34		startTime    time.Time
35		endTime      time.Time
36		status       string
37		attributes   map[string]string
38		seq          int64 // commit sequence, assigned when first stored
39	}
40	
41	// sameContent reports whether two spans with the same (trace_id, span_id)
42	// carry the same content, making the later one a replay rather than a
43	// conflict. Time instants compare regardless of the submitted zone.
44	func (sp *span) sameContent(other *span) bool {
45		return sp.traceID == other.traceID &&
46			sp.spanID == other.spanID &&
47			sp.parentSpanID == other.parentSpanID &&
48			sp.service == other.service &&
49			sp.name == other.name &&
50			sp.startTime.Equal(other.startTime) &&
51			sp.endTime.Equal(other.endTime) &&
52			sp.status == other.status &&
53			maps.Equal(sp.attributes, other.attributes)
54	}
55	
56	// spanKey builds the tenant-unique identity of a span from trace and span id.
57	// Both ids are lowercase hex of fixed length, so a NUL separator is
58	// unambiguous.
59	func spanKey(traceID, spanID string) string {
60		return traceID + "\x00" + spanID
61	}
62	
63	// checkAndApplySpans validates the batch against committed state (and against
64	// itself) and then commits it in array order. A false ok signals a content
65	// conflict on a repeated span; in that case no state is mutated. Replays —
66	// repeats of a (trace_id, span_id) with identical content — are counted but
67	// do not mutate state. Conflict and replay detection always runs before
68	// sampling: only spans not yet retained are subject to the tenant's sampling
69	// policy, decided on the trace id at trace_rate so a trace's spans and traced
70	// logs are kept or dropped together. Dropped spans leave no trace.
71	// sampling reports whether the policy in effect had any rate below 1, so the
72	// response can carry sampled_out.
73	func (s *metricStore) checkAndApplySpans(batch []*span) (accepted, replayed, sampledOutN int, sampling, ok bool) {
74		s.mu.Lock()
75		defer s.mu.Unlock()
76	
77		// First pass: conflict detection against committed spans and earlier
78		// spans in the same batch.
79		seen := make(map[string]*span, len(batch))
80		for _, sp := range batch {
81			key := spanKey(sp.traceID, sp.spanID)
82			if prev, dup := seen[key]; dup {
83				if !prev.sameContent(sp) {
84					return 0, 0, 0, false, false
85				}
86				continue
87			}
88			if existing, committed := s.spans[key]; committed && !existing.sameContent(sp) {
89				return 0, 0, 0, false, false
90			}
91			seen[key] = sp
92		}
93	
94		// Second pass: commit in array order.
95		policy := s.sampling
96		sampling = policy.active()
97		for _, sp := range batch {
98			key := spanKey(sp.traceID, sp.spanID)
99			if _, exists := s.spans[key]; exists {
100				replayed++
101				continue
102			}
103			if sampledOut(sp.traceID, policy.TraceRate) {
104				sampledOutN++
105				continue
106			}
107			s.spanSeq++
108			sp.seq = s.spanSeq
109			s.spans[key] = sp
110			accepted++
111		}
112		return accepted, replayed, sampledOutN, sampling, true
113	}
114	
115	// traceSnapshot is one consistent read of a trace's spans together with the
116	// retained logs carrying the same trace id.
117	type traceSnapshot struct {
118		spans []*span
119		logs  []*logEntry
120	}
121	
122	// getTrace returns the spans of traceID and the currently retained logs with
123	// that trace id. The found flag is false only when no span is stored; logs
124	// alone never create a trace.
125	func (s *metricStore) getTrace(traceID string) (traceSnapshot, bool) {
126		s.mu.RLock()
127		defer s.mu.RUnlock()
128	
129		var snap traceSnapshot
130		for _, sp := range s.spans {
131			if sp.traceID == traceID {
132				snap.spans = append(snap.spans, sp)
133			}
134		}
135		if len(snap.spans) == 0 {
136			return traceSnapshot{}, false
137		}
138		for _, e := range s.logs {
139			if e.traceID == traceID {
140				snap.logs = append(snap.logs, e)
141			}
142		}
143		sort.Slice(snap.spans, func(i, j int) bool {
144			a, b := snap.spans[i], snap.spans[j]
145			if !a.startTime.Equal(b.startTime) {
146				return a.startTime.Before(b.startTime)
147			}
148			return a.spanID < b.spanID
149		})
150		sort.Slice(snap.logs, func(i, j int) bool {
151			a, b := snap.logs[i], snap.logs[j]
152			if !a.timestamp.Equal(b.timestamp) {
153				return a.timestamp.Before(b.timestamp)
154			}
155			return a.id < b.id
156		})
157		return snap, true
158	}
