216		batch := make([]*span, 0, len(*env.Spans))
217		for _, raw := range *env.Spans {
218			var rs rawSpan
219			if !strictDecode(raw, &rs) {
220				return nil, false
221			}
222			if rs.TraceID == nil || rs.SpanID == nil || len(rs.ParentSpanID) == 0 ||
223				rs.Service == nil || rs.Name == nil || rs.StartTime == nil ||
224				rs.EndTime == nil || rs.Status == nil || rs.Attributes == nil {
225				return nil, false
226			}
227			traceID := *rs.TraceID
228			if !validTraceID(traceID) {
229				return nil, false
230			}
231			spanID := *rs.SpanID
232			if !validSpanID(spanID) {
233				return nil, false
234			}
235			// parent_span_id is exactly null or a span-id string; a missing field
236			// was rejected above. The parent span itself may arrive later.
237			var parentPtr *string
238			if err := json.Unmarshal(rs.ParentSpanID, &parentPtr); err != nil {
239				return nil, false
240			}
241			parentSpanID := ""
242			if parentPtr != nil {
243				parentSpanID = *parentPtr
244				if !validSpanID(parentSpanID) || parentSpanID == spanID {
245					return nil, false
246				}
247			}
248			service := *rs.Service
249			name := *rs.Name
