263			}
264			status := *rs.Status
265			if !spanStatuses[status] {
266				return nil, false
267			}
268			// attributes must be a JSON object of string values. RawMessage keeps
269			// explicit nulls visible: encoding/json would otherwise fold a null
270			// value into the empty string, and a whole-document null into a nil
271			// map; both are illegal here.
272			var rawAttrs map[string]json.RawMessage
273			if err := json.Unmarshal(rs.Attributes, &rawAttrs); err != nil || rawAttrs == nil {
274				return nil, false
275			}
276			attributes := make(map[string]string, len(rawAttrs))
277			for k, rawVal := range rawAttrs {
278				if !identPattern.MatchString(k) {
279					return nil, false
280				}
281				var value *string
282				if err := json.Unmarshal(rawVal, &value); err != nil || value == nil {
283					return nil, false
284				}
285				attributes[k] = *value
286			}
287			batch = append(batch, &span{
288				traceID:      traceID,
289				spanID:       spanID,
290				parentSpanID: parentSpanID,
291				service:      service,
292				name:         name,
293				startTime:    startTime,
294				endTime:      endTime,
295				status:       status,
296				attributes:   attributes,
297			})
298		}
299		return batch, true
300	}
301	
302	// validSpanID reports whether id is exactly 16 lowercase hex characters.
303	func validSpanID(id string) bool {
304		if len(id) != 16 {
305			return false
306		}
307		for i := 0; i < len(id); i++ {
308			c := id[i]
309			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
310				return false
311			}
312		}
313		return true
314	}
315	
316	// ---- HTTP handlers ---------------------------------------------------------
317	
