1	package server
2	
3	import (
4		"crypto/hmac"
5		"crypto/sha256"
6		"encoding/base64"
7		"encoding/json"
8		"net/http"
9		"net/url"
10		"sort"
11		"strconv"
12		"time"
13	)
14	
15	const (
16		defaultTraceLimit = 100
17		maxTraceLimit     = 200
18	)
19	
20	// traceFilter is the immutable, signed condition set of a trace search. Both
21	// time bounds are mandatory; service/name/status are empty when not requested.
22	type traceFilter struct {
23		start   time.Time
24		end     time.Time
25		service string
26		name    string
27		status  string
28	}
29	
30	// spanFeatureMatch reports whether sp alone satisfies every requested span
31	// feature. The multiple feature conditions must hold for the same span rather
32	// than being spread across spans of the trace.
33	func (f *traceFilter) spanFeatureMatch(sp *span) bool {
34		if f.service != "" && sp.service != f.service {
35			return false
36		}
37		if f.name != "" && sp.name != f.name {
38			return false
39		}
40		if f.status != "" && sp.status != f.status {
41			return false
42		}
43		return true
44	}
45	
46	// traceAccumulator is the per-trace fold of retained spans.
47	type traceAccumulator struct {
48		start        time.Time
49		end          time.Time
50		count        int
51		services     map[string]struct{}
52		hasOK        bool
53		hasError     bool
54		featureMatch bool
55	}
56	
57	// traceSummary is one assembled trace collection entry.
58	type traceSummary struct {
59		traceID   string
60		startTime time.Time
61		endTime   time.Time
62		spanCount int
63		services  []string
64		status    string
65	}
66	
67	// queryTraces returns the page of trace summaries matching the filter within
68	// the snapshot (spans with seq <= snapshotSeq), strictly after the position
69	// (afterStart, afterTraceID) in result order, plus whether more entries
70	// remain. Result order is earliest span start descending, trace id ascending
71	// within one instant.
72	func (s *metricStore) queryTraces(f *traceFilter, snapshotSeq int64, afterStart time.Time, afterTraceID string, hasAfter bool, limit int) ([]traceSummary, bool) {
73		s.mu.RLock()
74		defer s.mu.RUnlock()
75	
76		accs := make(map[string]*traceAccumulator)
77		for _, sp := range s.spans {
78			if sp.seq > snapshotSeq {
79				continue // committed after the snapshot anchor; never mixes in
80			}
81			acc := accs[sp.traceID]
82			if acc == nil {
83				acc = &traceAccumulator{
84					start:    sp.startTime,
85					end:      sp.endTime,
86					services: make(map[string]struct{}),
87				}
88				accs[sp.traceID] = acc
89			}
90			acc.count++
91			if sp.startTime.Before(acc.start) {
92				acc.start = sp.startTime
93			}
94			if sp.endTime.After(acc.end) {
95				acc.end = sp.endTime
96			}
97			acc.services[sp.service] = struct{}{}
98			switch sp.status {
99			case "error":
100				acc.hasError = true
101			case "ok":
102				acc.hasOK = true
103			}
104			if f.spanFeatureMatch(sp) {
105				acc.featureMatch = true
106			}
107		}
108	
109		matched := make([]traceSummary, 0)
110		for traceID, acc := range accs {
111			// The trace time is the earliest stored span start; it must fall into
112			// the half-open [start, end) window.
113			if acc.start.Before(f.start) || !acc.start.Before(f.end) {
114				continue
115			}
116			if !acc.featureMatch {
117				continue
118			}
119			if hasAfter && !summaryComesAfter(acc.start, traceID, afterStart, afterTraceID) {
120				continue
121			}
122			services := make([]string, 0, len(acc.services))
123			for svc := range acc.services {
124				services = append(services, svc)
125			}
126			sort.Strings(services)
127			status := "unset"
128			switch {
129			case acc.hasError:
130				status = "error"
131			case acc.hasOK:
132				status = "ok"
133			}
134			matched = append(matched, traceSummary{
135				traceID:   traceID,
136				startTime: acc.start,
137				endTime:   acc.end,
138				spanCount: acc.count,
139				services:  services,
140				status:    status,
141			})
142		}
143		sort.Slice(matched, func(i, j int) bool {
144			a, b := matched[i], matched[j]
145			if !a.startTime.Equal(b.startTime) {
146				return a.startTime.After(b.startTime)
147			}
148			return a.traceID < b.traceID
149		})
150	
151		more := len(matched) > limit
152		if more {
153			matched = matched[:limit]
154		}
155		return matched, more
156	}
157	
158	// summaryComesAfter reports whether an entry at (start, traceID) sorts strictly
159	// after the page position in start-descending, trace-id-ascending order.
160	func summaryComesAfter(start time.Time, traceID string, afterStart time.Time, afterTraceID string) bool {
161		if start.Equal(afterStart) {
162			return traceID > afterTraceID
163		}
164		return start.Before(afterStart)
165	}
