169	// traceCursor pins the first request's conditions, page size and snapshot
170	// upper bound, plus the position the next page continues from.
171	type traceCursor struct {
172		V         int    `json:"v"`
173		Tenant    string `json:"tenant"`
174		Start     string `json:"start"`
175		End       string `json:"end"`
176		Service   string `json:"service,omitempty"`
177		Name      string `json:"name,omitempty"`
178		Status    string `json:"status,omitempty"`
179		Limit     int    `json:"limit"`
180		Snapshot  int64  `json:"snapshot"`
181		LastStart string `json:"last_start,omitempty"`
182		LastTrace string `json:"last_trace,omitempty"`
183	}
