185	func encodeTraceCursor(c *traceCursor) string {
186		payload, _ := json.Marshal(c)
187		mac := hmac.New(sha256.New, cursorKey)
188		mac.Write(payload)
189		return base64.RawURLEncoding.EncodeToString(payload) + "." +
190			base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
191	}
