193	// decodeTraceCursor parses and validates a trace cursor token. The boolean is
194	// false for any malformed, tampered or otherwise unusable token.
195	func decodeTraceCursor(token string) (*traceCursor, bool) {
196		payload, _, ok := parseCursorToken(token)
197		if !ok {
198			return nil, false
199		}
200		var c traceCursor
201		if !strictDecode(payload, &c) {
202			return nil, false
203		}
204		if c.V != 1 || c.Tenant == "" || c.Limit < 1 || c.Limit > maxTraceLimit || c.Snapshot < 0 {
205			return nil, false
206		}
207		start, err := time.Parse(time.RFC3339Nano, c.Start)
208		if err != nil {
209			return nil, false
210		}
211		end, err := time.Parse(time.RFC3339Nano, c.End)
212		if err != nil {
213			return nil, false
214		}
215		if !start.Before(end) {
216			return nil, false
217		}
218		if c.Status != "" && !spanStatuses[c.Status] {
219			return nil, false
220		}
221		switch {
222		case c.LastStart == "" && c.LastTrace == "":
223			// First page position: neither field is set.
224		case c.LastStart != "" && c.LastTrace != "":
225			if _, err := time.Parse(time.RFC3339Nano, c.LastStart); err != nil {
226				return nil, false
227			}
228			if !validTraceID(c.LastTrace) {
229				return nil, false
230			}
231		default:
232			return nil, false // position fields must appear together
233		}
234		return &c, true
235	}
236	
237	// ---- HTTP handlers ---------------------------------------------------------
238	
239	func handleTracesGet(w http.ResponseWriter, r *http.Request) {
240		if r.Method != http.MethodGet {
241			w.Header().Set("Allow", http.MethodGet)
242			writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
243			return
244		}
245	
246		store := tenantStore(r)
247		values, err := url.ParseQuery(r.URL.RawQuery)
248		if err != nil {
249			writeAPIError(w, "invalid_trace_query", http.StatusBadRequest)
250			return
251		}
252	
253		if cursors, present := values["cursor"]; present {
254			// A follow-up request carries exactly one cursor and nothing else.
255			if len(values) != 1 || len(cursors) != 1 {
256				writeAPIError(w, "invalid_trace_cursor", http.StatusBadRequest)
257				return
258			}
259			cursor, ok := decodeTraceCursor(cursors[0])
260			if !ok || cursor.Tenant != tenantName(r) {
261				writeAPIError(w, "invalid_trace_cursor", http.StatusBadRequest)
262				return
263			}
264			serveTracePage(w, store, cursor)
265			return
266		}
267	
268		filter, limit, ok := parseTraceQuery(values)
269		if !ok {
270			writeAPIError(w, "invalid_trace_query", http.StatusBadRequest)
271			return
272		}
273	
274		store.mu.RLock()
275		snapshot := store.spanSeq
276		store.mu.RUnlock()
277	
278		cursor := &traceCursor{
279			V:        1,
280			Tenant:   tenantName(r),
281			Start:    filter.start.UTC().Format(time.RFC3339Nano),
282			End:      filter.end.UTC().Format(time.RFC3339Nano),
283			Service:  filter.service,
284			Name:     filter.name,
285			Status:   filter.status,
286			Limit:    limit,
287			Snapshot: snapshot,
288		}
289		serveTracePage(w, store, cursor)
290	}
291	
292	// serveTracePage runs the paginated query described by cursor and writes the
293	// response, refreshing the cursor's position for the next page.
294	func serveTracePage(w http.ResponseWriter, store *metricStore, cursor *traceCursor) {
295		// Both bounds were validated when the cursor was minted or decoded.
296		start, _ := time.Parse(time.RFC3339Nano, cursor.Start)
297		end, _ := time.Parse(time.RFC3339Nano, cursor.End)
298		filter := &traceFilter{
299			start:   start,
300			end:     end,
301			service: cursor.Service,
302			name:    cursor.Name,
303			status:  cursor.Status,
304		}
305	
306		var afterStart time.Time
307		hasAfter := cursor.LastStart != ""
308		if hasAfter {
309			afterStart, _ = time.Parse(time.RFC3339Nano, cursor.LastStart)
310		}
311	
312		page, more := store.queryTraces(filter, cursor.Snapshot, afterStart, cursor.LastTrace, hasAfter, cursor.Limit)
313	
314		traces := make([]traceSummaryJSON, 0, len(page))
315		for _, sum := range page {
316			traces = append(traces, sum.wireJSON())
317		}
318	
319		var nextCursor *string
320		if more {
321			last := page[len(page)-1]
322			cursor.LastStart = last.startTime.UTC().Format(time.RFC3339Nano)
323			cursor.LastTrace = last.traceID
324			token := encodeTraceCursor(cursor)
325			nextCursor = &token
326		}
327	
328		writeJSON(w, http.StatusOK, map[string]any{"traces": traces, "next_cursor": nextCursor})
329	}
330	
331	// parseTraceQuery validates the first-request query parameters and builds the
332	// filter. start and end are mandatory and unique; service, name, status and
333	// limit are optional but may appear at most once; every other name is unknown.
334	func parseTraceQuery(values url.Values) (*traceFilter, int, bool) {
335		filter := &traceFilter{}
336		limit := defaultTraceLimit
337		hasStart, hasEnd := false, false
338	
339		for key, vals := range values {
340			// Every accepted parameter is single-valued: duplicates are invalid.
341			if len(vals) != 1 {
342				return nil, 0, false
343			}
344			value := vals[0]
345			switch key {
346			case "start":
347				ts, err := time.Parse(time.RFC3339Nano, value)
348				if err != nil {
349					return nil, 0, false
350				}
351				filter.start, hasStart = ts, true
352			case "end":
353				ts, err := time.Parse(time.RFC3339Nano, value)
354				if err != nil {
355					return nil, 0, false
356				}
357				filter.end, hasEnd = ts, true
358			case "service":
359				if value == "" {
360					return nil, 0, false
361				}
362				filter.service = value
363			case "name":
364				if value == "" {
365					return nil, 0, false
366				}
367				filter.name = value
368			case "status":
369				if !spanStatuses[value] {
370					return nil, 0, false
371				}
372				filter.status = value
373			case "limit":
374				n, err := strconv.Atoi(value)
375				if err != nil || n < 1 || n > maxTraceLimit {
376					return nil, 0, false
377				}
378				limit = n
379			default:
380				return nil, 0, false
381			}
382		}
383	
384		if !hasStart || !hasEnd || !filter.start.Before(filter.end) {
