266	// notificationPlan evaluates alerts and routes against one consistent snapshot
267	// shared with metrics, alert rules, silences and inhibit rules. Only alerts
268	// that are firing and neither silenced nor inhibited participate. Each
269	// participating alert is delivered through the covering route with the
270	// smallest priority, ties broken by the smallest route id; participating
271	// alerts with no covering route are reported as unrouted.
272	func (s *metricStore) notificationPlan() ([]deliveryOutput, []string) {
273		s.mu.RLock()
274		defer s.mu.RUnlock()
275	
276		alerts := s.evalAlertsLocked()
277		// Routes are sorted by id, so scanning in order and replacing the winner
278		// only on a strictly smaller priority also resolves priority ties toward
279		// the smallest id.
280		routes := s.snapshotNotificationRoutesLocked()
281	
282		deliveries := make([]deliveryOutput, 0)
283		unrouted := make([]string, 0)
284		for _, al := range alerts {
285			if al.State != "firing" || al.Silenced || al.Inhibited {
286				continue
287			}
288			var best *notificationRoute
289			for _, rt := range routes {
290				if !containsString(rt.ruleIDs, al.ID) {
291					continue
292				}
293				if best == nil || rt.priority < best.priority {
294					best = rt
295				}
296			}
297			if best == nil {
298				unrouted = append(unrouted, al.ID)
299				continue
300			}
301			deliveries = append(deliveries, deliveryOutput{
302				AlertID:  al.ID,
303				Receiver: best.receiver,
304				RouteID:  best.id,
305			})
306		}
307	
308		// Alert evaluation already returns alerts sorted by id, but enforce the
309		// documented output order explicitly.
310		sort.Slice(deliveries, func(i, j int) bool { return deliveries[i].AlertID < deliveries[j].AlertID })
311		sort.Strings(unrouted)
312		return deliveries, unrouted
313	}
