1	package server
2	
3	import (
4		"encoding/json"
5		"io"
6		"mime"
7		"net/http"
8		"net/url"
9		"sort"
10		"strconv"
11		"strings"
12	)
13	
14	const (
15		discoveryTargetsPath       = "/api/v1/discovery-targets"
16		discoveryTargetsReloadPath = "/api/v1/discovery-targets/reload"
17	
18		maxDiscoveryTargets = 1000
19	)
20	
21	// discoveryTarget is one immutable scrape target. Snapshots are swapped
22	// atomically, so readers never observe a half-updated target list.
23	type discoveryTarget struct {
24		id      string
25		url     string // echoed verbatim from the accepted request
26		labels  map[string]string
27		enabled bool
28	}
29	
30	// discoverySnapshot is the tenant's full target configuration plus the
31	// generation that last changed its content.
32	type discoverySnapshot struct {
33		generation int64
34		targets    []discoveryTarget // sorted by id, immutable after publication
35	}
36	
37	// emptyDiscoverySnapshot is the restart baseline: generation 0, no targets.
38	func emptyDiscoverySnapshot() *discoverySnapshot {
39		return &discoverySnapshot{generation: 0, targets: []discoveryTarget{}}
40	}
41	
42	// ---- JSON wire shapes ------------------------------------------------------
43	
44	type discoveryTargetJSON struct {
45		ID      string            `json:"id"`
46		URL     string            `json:"url"`
47		Labels  map[string]string `json:"labels"`
48		Enabled bool              `json:"enabled"`
49	}
50	
51	func discoverySnapshotWireJSON(snap *discoverySnapshot) map[string]any {
52		targets := make([]discoveryTargetJSON, 0, len(snap.targets))
53		for _, t := range snap.targets {
54			targets = append(targets, discoveryTargetJSON{
55				ID:      t.id,
56				URL:     t.url,
57				Labels:  copyLabels(t.labels),
58				Enabled: t.enabled,
59			})
60		}
61		return map[string]any{"generation": snap.generation, "targets": targets}
62	}
63	
64	// ---- request decoding ------------------------------------------------------
65	
66	type discoveryEnvelope struct {
67		Targets *[]json.RawMessage `json:"targets"`
68	}
69	
70	type rawDiscoveryTarget struct {
71		ID      *string            `json:"id"`
72		URL     *string            `json:"url"`
73		Labels  *map[string]string `json:"labels"`
74		Enabled *bool              `json:"enabled"`
75	}
76	
77	// decodeDiscoveryTargets parses and fully validates a reload body. It never
78	// returns a partially validated snapshot; the returned targets are sorted by
79	// id so content comparison and responses share one canonical order.
80	func decodeDiscoveryTargets(body []byte) ([]discoveryTarget, bool) {
81		var env discoveryEnvelope
82		if !strictDecode(body, &env) || env.Targets == nil {
83			return nil, false
84		}
85		raw := *env.Targets
86		if len(raw) > maxDiscoveryTargets {
87			return nil, false
88		}
89	
90		targets := make([]discoveryTarget, 0, len(raw))
91		seen := make(map[string]bool, len(raw))
92		for _, item := range raw {
93			var rt rawDiscoveryTarget
94			if !strictDecode(item, &rt) {
95				return nil, false
96			}
97			if rt.ID == nil || rt.URL == nil || rt.Labels == nil || rt.Enabled == nil {
98				return nil, false
99			}
100			id := *rt.ID
101			if !identPattern.MatchString(id) || seen[id] {
102				return nil, false
103			}
104			seen[id] = true
105	
106			if !validDiscoveryURL(*rt.URL) {
107				return nil, false
108			}
109	
110			labels := *rt.Labels
111			if labels == nil {
112				return nil, false // explicit null labels
113			}
114			for k := range labels {
115				if !identPattern.MatchString(k) {
116					return nil, false
117				}
118			}
119	
120			targets = append(targets, discoveryTarget{
121				id:      id,
122				url:     *rt.URL,
123				labels:  copyLabels(labels),
124				enabled: *rt.Enabled,
125			})
126		}
127	
128		sort.Slice(targets, func(i, j int) bool { return targets[i].id < targets[j].id })
129		return targets, true
130	}
131	
132	// validDiscoveryURL accepts only absolute http/https URLs with a non-empty
133	// host and no userinfo, fragment or invalid port.
134	func validDiscoveryURL(raw string) bool {
135		if raw == "" || strings.Contains(raw, "#") {
136			return false
137		}
138		u, err := url.Parse(raw)
139		if err != nil {
140			return false
141		}
142		scheme := strings.ToLower(u.Scheme)
143		if scheme != "http" && scheme != "https" {
144			return false
145		}
146		if u.User != nil || u.Hostname() == "" {
147			return false
148		}
149		if port := u.Port(); port != "" {
150			n, err := strconv.Atoi(port)
151			if err != nil || n > 65535 {
152				return false
153			}
154		}
155		return true
156	}
157	
158	// ---- store operations ------------------------------------------------------
159	
160	// discoverySnapshotNow returns the tenant's current immutable snapshot.
161	func (s *metricStore) discoverySnapshotNow() *discoverySnapshot {
162		s.mu.RLock()
163		defer s.mu.RUnlock()
164		return s.discovery
165	}
166	
167	// reloadDiscoveryTargets atomically replaces the snapshot after validation.
168	// The generation advances only when the content — ids, urls, label sets or
169	// enabled flags — actually changes; target and label-key order never count.
170	func (s *metricStore) reloadDiscoveryTargets(targets []discoveryTarget) *discoverySnapshot {
171		s.mu.Lock()
172		defer s.mu.Unlock()
173		cur := s.discovery
174		if !discoveryTargetsEqual(cur.targets, targets) {
175			cur = &discoverySnapshot{generation: cur.generation + 1, targets: targets}
176			s.discovery = cur
177		}
178		return cur
179	}
180	
181	// discoveryTargetsEqual compares two id-sorted target lists by content.
182	func discoveryTargetsEqual(a, b []discoveryTarget) bool {
183		if len(a) != len(b) {
184			return false
185		}
186		for i := range a {
187			if a[i].id != b[i].id || a[i].url != b[i].url || a[i].enabled != b[i].enabled {
188				return false
189			}
190			if len(a[i].labels) != len(b[i].labels) {
191				return false
192			}
193			for k, v := range a[i].labels {
194				if bv, ok := b[i].labels[k]; !ok || bv != v {
195					return false
196				}
197			}
198		}
199		return true
200	}
201	
202	// ---- HTTP handlers ---------------------------------------------------------
203	
204	func registerDiscoveryTargetHandlers(mux *http.ServeMux) {
205		mux.HandleFunc(discoveryTargetsPath, func(w http.ResponseWriter, r *http.Request) {
206			if r.Method != http.MethodGet {
207				w.Header().Set("Allow", http.MethodGet)
208				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
209				return
210			}
211			// The query endpoint takes no parameters at all.
212			if r.URL.RawQuery != "" {
213				writeAPIError(w, "invalid_discovery_query", http.StatusBadRequest)
214				return
215			}
216			writeJSON(w, http.StatusOK, discoverySnapshotWireJSON(tenantStore(r).discoverySnapshotNow()))
217		})
218	
219		mux.HandleFunc(discoveryTargetsReloadPath, func(w http.ResponseWriter, r *http.Request) {
220			if r.Method != http.MethodPost {
